INSERT INTO `questions` (`question_id`, `theme_id`, `level`, `question_type`, `question_text`, `image_url`, `audio_text`, `options`, `correct_answer`, `explanation`, `difficulty`, `created_by`, `is_active`, `created_at`, `updated_at`) VALUES (1,1,'vocabulary','mcq','Which animal says \'woof\'?',NULL,NULL,'[\"dog\", \"cat\", \"pig\", \"bird\"]','dog','Dog barks and says woof.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(2,1,'vocabulary','mcq','Where do you see many animals together?',NULL,NULL,'[\"zoo\", \"school\", \"home\", \"store\"]','zoo','A zoo keeps many animals.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(3,1,'vocabulary','mcq','Which is the biggest animal?',NULL,NULL,'[\"elephant\", \"cat\", \"rabbit\", \"bird\"]','elephant','Elephants are the largest land animals.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(4,1,'vocabulary','mcq','This animal has a very long nose. It is an _____.',NULL,NULL,'[\"elephant\", \"snake\", \"monkey\", \"lion\"]','elephant','Elephants have long trunks.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(5,1,'vocabulary','mcq','A ___ lives in the jungle and has a mane.',NULL,NULL,'[\"lion\", \"tiger\", \"bear\", \"rabbit\"]','lion','A lion has a fluffy mane.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(6,1,'sentence','fill_blank','Where ___ you? I am in the park.',NULL,NULL,'[]','are','Where are you? Present tense question.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(7,1,'sentence','fill_blank','I ___ a big elephant at the zoo.',NULL,NULL,'[]','see','I see — present tense to observe.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(8,1,'sentence','ordering','is / a / There / park / big',NULL,NULL,'[]','There is a big park','Sentence: There is a big park.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(9,1,'sentence','mcq','Which sentence is correct?',NULL,NULL,'[\"I see a big elephant.\", \"I sees a big elephant.\", \"I seed a big elephant.\", \"I seeing a big elephant.\"]','I see a big elephant.','Use base form see after I.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(10,1,'reading','mcq','Tom is at the zoo. He sees a big elephant and a monkey. The monkey is funny. What does Tom see?',NULL,NULL,'[\"elephant and monkey\", \"lion and tiger\", \"dog and cat\", \"bird and snake\"]','elephant and monkey','Reading comprehension: Tom sees elephant and monkey.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(11,2,'vocabulary','mcq','Which fruit is yellow and long?',NULL,NULL,'[\"banana\", \"apple\", \"orange\", \"cake\"]','banana','Bananas are yellow and curved.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(12,2,'vocabulary','mcq','What do you drink when you are thirsty?',NULL,NULL,'[\"water\", \"egg\", \"pizza\", \"cake\"]','water','Water quenches thirst.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(13,2,'vocabulary','mcq','Which food is round and flat with cheese?',NULL,NULL,'[\"pizza\", \"soup\", \"bread\", \"egg\"]','pizza','Pizza is round with cheese and toppings.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(14,2,'vocabulary','mcq','You have it for breakfast. It is a fried ___.',NULL,NULL,'[\"egg\", \"juice\", \"cake\", \"fish\"]','egg','Fried egg is a common breakfast food.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(15,2,'vocabulary','mcq','What do you drink made from fruit?',NULL,NULL,'[\"juice\", \"milk\", \"soup\", \"water\"]','juice','Juice is made by pressing fruit.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(16,2,'sentence','fill_blank','I ___ apples. They are yummy!',NULL,NULL,'[]','like','I like — to express preference.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(17,2,'sentence','fill_blank','I am ___. I want to eat a hot dog.',NULL,NULL,'[]','hungry','Hungry means you want to eat.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(18,2,'sentence','ordering','want / I / eat / to / pizza',NULL,NULL,'[]','I want to eat pizza','I want to eat + food.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(19,2,'sentence','mcq','Which sentence uses like correctly?',NULL,NULL,'[\"I like bananas.\", \"I likes bananas.\", \"I am like bananas.\", \"I liking bananas.\"]','I like bananas.','Subject + like + noun.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(20,2,'reading','mcq','Amy is hungry. She wants to eat lunch. She has a sandwich and juice. What does Amy have for lunch?',NULL,NULL,'[\"sandwich and juice\", \"pizza and milk\", \"hamburger and water\", \"cake and tea\"]','sandwich and juice','Comprehension: Amy has sandwich and juice.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(21,3,'vocabulary','mcq','Who teaches you at school?',NULL,NULL,'[\"teacher\", \"student\", \"friend\", \"brother\"]','teacher','Teachers teach students.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(22,3,'vocabulary','mcq','Your mom\'s mom is your ___.',NULL,NULL,'[\"grandmother\", \"sister\", \"mother\", \"aunt\"]','grandmother','Grandmother is the mother of a parent.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(23,3,'vocabulary','mcq','A person you learn with is your ___.',NULL,NULL,'[\"classmate\", \"teacher\", \"father\", \"brother\"]','classmate','Classmates learn together.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(24,3,'vocabulary','mcq','Your parents son (not you) is your ___.',NULL,NULL,'[\"brother\", \"sister\", \"friend\", \"student\"]','brother','Brother is a male sibling.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(25,3,'vocabulary','mcq','Someone you play with and trust is your ___.',NULL,NULL,'[\"friend\", \"teacher\", \"student\", \"classmate\"]','friend','A friend is a person you care about.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(26,3,'sentence','fill_blank','___ is my brother. He is tall.',NULL,NULL,'[]','He','He refers to a male person.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(27,3,'sentence','fill_blank','She is a good ___.',NULL,NULL,'[]','teacher','Teacher is a person who teaches.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(28,3,'sentence','ordering','my / She / teacher / is / good',NULL,NULL,'[]','She is my good teacher','She is my good teacher.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(29,3,'sentence','mcq','How do you introduce your dad?',NULL,NULL,'[\"He is my father.\", \"She is my father.\", \"It is my father.\", \"They is my father.\"]','He is my father.','Use He for male.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(30,3,'reading','mcq','This is my family. My father is tall. My mother is kind. I have a sister. She is funny. How many people are in the family?',NULL,NULL,'[\"four\", \"three\", \"five\", \"two\"]','four','Father + Mother + sister + speaker = 4.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(31,4,'vocabulary','mcq','What day comes after Sunday?',NULL,NULL,'[\"Monday\", \"Friday\", \"Saturday\", \"Tuesday\"]','Monday','Monday is the first day of the week.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(32,4,'vocabulary','mcq','What number is after nine?',NULL,NULL,'[\"ten\", \"eight\", \"seven\", \"eleven\"]','ten','Nine + one = ten.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(33,4,'vocabulary','mcq','When the sun goes down and it gets dark, it is ___.',NULL,NULL,'[\"night\", \"morning\", \"afternoon\", \"evening\"]','night','Night is after evening when it is dark.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(34,4,'vocabulary','mcq','You wake up and eat breakfast. It is the ___.',NULL,NULL,'[\"morning\", \"night\", \"afternoon\", \"evening\"]','morning','Morning is the start of the day.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(35,4,'vocabulary','mcq','How many days are in a week?',NULL,NULL,'[\"seven\", \"five\", \"six\", \"eight\"]','seven','Monday to Sunday = 7 days.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(36,4,'sentence','fill_blank','Today ___ Monday. We go to school.',NULL,NULL,'[]','is','Today is Monday — linking verb.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(37,4,'sentence','fill_blank','I get ___ in the morning.',NULL,NULL,'[]','up','Get up means to wake up and rise.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(38,4,'sentence','ordering','morning / I / up / in / get / the',NULL,NULL,'[]','I get up in the morning','I get up in the morning.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(39,4,'sentence','mcq','Which is correct?',NULL,NULL,'[\"Today is Tuesday.\", \"Today are Tuesday.\", \"Today be Tuesday.\", \"Today was Tuesday.\"]','Today is Tuesday.','Today + is for present.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(40,4,'reading','mcq','It is Monday morning. Tim gets up at seven. He eats breakfast. Then he goes to school. What time does Tim get up?',NULL,NULL,'[\"seven\", \"eight\", \"six\", \"nine\"]','seven','Tim gets up at seven.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(41,5,'vocabulary','mcq','You use this to see. It is your ___.',NULL,NULL,'[\"eye\", \"ear\", \"nose\", \"mouth\"]','eye','Eyes are for seeing.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(42,5,'vocabulary','mcq','You use this to hear music. It is your ___.',NULL,NULL,'[\"ear\", \"eye\", \"hand\", \"foot\"]','ear','Ears are for hearing.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(43,5,'vocabulary','mcq','When you smile, you show your ___.',NULL,NULL,'[\"mouth\", \"nose\", \"ear\", \"head\"]','mouth','The mouth opens to smile.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(44,5,'vocabulary','mcq','If you fall and cannot walk, your ___ hurts.',NULL,NULL,'[\"foot\", \"ear\", \"eye\", \"hand\"]','foot','Foot is used for walking.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(45,5,'vocabulary','mcq','You feel this when you get a gift. You are ___.',NULL,NULL,'[\"happy\", \"sad\", \"tired\", \"angry\"]','happy','Gifts make people happy.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(46,5,'sentence','fill_blank','I am very ___ today. I got a new toy!',NULL,NULL,'[]','happy','Happy = feeling joy.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(47,5,'sentence','fill_blank','My ___ is long. I can run fast.',NULL,NULL,'[]','leg','Leg is a body part used for running.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(48,5,'sentence','ordering','very / I / today / happy / am',NULL,NULL,'[]','I am very happy today','I am very happy today.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(49,5,'sentence','mcq','Which is correct?',NULL,NULL,'[\"My eyes are big.\", \"My eyes is big.\", \"My eye are big.\", \"My eyes am big.\"]','My eyes are big.','Eyes is plural, use are.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(50,5,'reading','mcq','Ben is sick today. His head hurts. His nose is cold. He is sad. He cannot go to school. Why is Ben sad?',NULL,NULL,'[\"He is sick.\", \"He is happy.\", \"He is hungry.\", \"He is tired.\"]','He is sick.','Ben is sad because he is sick.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(51,6,'vocabulary','mcq','Grass is this color. It is ___.',NULL,NULL,'[\"green\", \"red\", \"blue\", \"yellow\"]','green','Grass is green.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(52,6,'vocabulary','mcq','The sky on a sunny day is ___.',NULL,NULL,'[\"blue\", \"black\", \"brown\", \"red\"]','blue','Clear sky is blue.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(53,6,'vocabulary','mcq','You wear this on your head when it is sunny. It is a ___.',NULL,NULL,'[\"hat\", \"shoe\", \"jacket\", \"dress\"]','hat','Hats protect from sun.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(54,6,'vocabulary','mcq','This is a color between red and yellow. It is ___.',NULL,NULL,'[\"orange\", \"pink\", \"purple\", \"brown\"]','orange','Orange is between red and yellow.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(55,6,'vocabulary','mcq','You wear this when it is cold. It is a ___.',NULL,NULL,'[\"jacket\", \"shorts\", \"T-shirt\", \"dress\"]','jacket','Jackets keep you warm.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(56,6,'sentence','fill_blank','I have a ___ jacket. It looks like fire!',NULL,NULL,'[]','red','Red is the color of fire.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(57,6,'sentence','fill_blank','She wears a ___ dress today.',NULL,NULL,'[]','blue','Blue describes the dress color.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(58,6,'sentence','ordering','a / I / jacket / red / have',NULL,NULL,'[]','I have a red jacket','I have a red jacket.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(59,6,'sentence','mcq','Which is correct?',NULL,NULL,'[\"I have a blue hat.\", \"I have blue a hat.\", \"I have hat a blue.\", \"Blue I have a hat.\"]','I have a blue hat.','Article + adjective + noun order.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(60,6,'reading','mcq','Lily is getting dressed. She puts on a white T-shirt. She wears blue shorts. She puts on her yellow hat. What color is her T-shirt?',NULL,NULL,'[\"white\", \"blue\", \"yellow\", \"red\"]','white','Lily T-shirt is white.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(61,7,'vocabulary','mcq','You write with this. It is a ___.',NULL,NULL,'[\"pen\", \"desk\", \"ruler\", \"eraser\"]','pen','Pens are for writing.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(62,7,'vocabulary','mcq','You sit at this in class. It is a ___.',NULL,NULL,'[\"desk\", \"book\", \"ruler\", \"computer\"]','desk','Desks are used in classrooms.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(63,7,'vocabulary','mcq','You use this to remove pencil marks. It is an ___.',NULL,NULL,'[\"eraser\", \"pencil\", \"ruler\", \"pen\"]','eraser','Erasers rub out mistakes.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(64,7,'vocabulary','mcq','You go here to learn. It is a ___.',NULL,NULL,'[\"school\", \"store\", \"park\", \"zoo\"]','school','School is for learning.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(65,7,'vocabulary','mcq','You keep pens and pencils in a ___.',NULL,NULL,'[\"pencil box\", \"book bag\", \"notebook\", \"ruler\"]','pencil box','Pencil boxes store stationery.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(66,7,'sentence','fill_blank','This is ___ pencil box. Do not touch it!',NULL,NULL,'[]','my','My shows possession.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(67,7,'sentence','fill_blank','May I borrow your ___?',NULL,NULL,'[]','eraser','Eraser is common to borrow.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(68,7,'sentence','ordering','my / This / pencil / is / box',NULL,NULL,'[]','This is my pencil box','This is my pencil box.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(69,7,'sentence','mcq','How do you ask to borrow a book?',NULL,NULL,'[\"Can I borrow your book?\", \"Can I borrows your book?\", \"Can I borrowed your book?\", \"Can borrow I your book?\"]','Can I borrow your book?','Can + subject + base verb.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(70,7,'reading','mcq','Sam is in the classroom. He has a book, a pen, and an eraser on his desk. He forgets his ruler. What does Sam forget?',NULL,NULL,'[\"ruler\", \"book\", \"pen\", \"eraser\"]','ruler','Sam forgets his ruler.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(71,8,'vocabulary','mcq','When the sun shines and there are no clouds, it is ___.',NULL,NULL,'[\"sunny\", \"rainy\", \"cloudy\", \"windy\"]','sunny','Sunny means the sun is out.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(72,8,'vocabulary','mcq','When water falls from the sky, it is ___.',NULL,NULL,'[\"rainy\", \"sunny\", \"windy\", \"cloudy\"]','rainy','Rainy means rain is falling.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(73,8,'vocabulary','mcq','After summer comes ___.',NULL,NULL,'[\"fall\", \"spring\", \"winter\", \"morning\"]','fall','Summer → Fall → Winter → Spring.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(74,8,'vocabulary','mcq','In ___, flowers bloom and it gets warm.',NULL,NULL,'[\"spring\", \"winter\", \"fall\", \"summer\"]','spring','Spring is warm with blooming flowers.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(75,8,'vocabulary','mcq','The coldest season is ___.',NULL,NULL,'[\"winter\", \"summer\", \"spring\", \"fall\"]','winter','Winter is the coldest season.',1,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(76,8,'sentence','fill_blank','How is the ___? It is sunny today.',NULL,NULL,'[]','weather','Weather describes outdoor conditions.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(77,8,'sentence','fill_blank','It is ___ and warm today. Let us play outside!',NULL,NULL,'[]','sunny','Sunny and warm = good weather.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(78,8,'sentence','ordering','sunny / It / and / is / warm',NULL,NULL,'[]','It is sunny and warm','It is sunny and warm.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(79,8,'sentence','mcq','Which is correct?',NULL,NULL,'[\"It is rainy today.\", \"It are rainy today.\", \"It is rain today.\", \"It raining today.\"]','It is rainy today.','It is + adjective for weather.',2,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(80,8,'reading','mcq','Today is Saturday. It is cold and windy. Mom says it will snow. Jack wears his jacket. What is the weather like?',NULL,NULL,'[\"cold and windy\", \"sunny and warm\", \"hot and rainy\", \"cloudy and cool\"]','cold and windy','The weather is cold and windy.',3,NULL,1,'2026-06-08 05:13:27','2026-06-08 05:13:27'),(81,9,'vocabulary','image_choice','Look at the picture. What is his name?','/images/super-fun/mike.svg',NULL,'[\"Mike\", \"Ken\", \"Emma\", \"Alan\"]','Mike','Mike 是故事裡戴眼鏡、會自我介紹的男孩。',1,NULL,1,'2026-07-13 15:44:19','2026-07-16 21:04:36'),(82,9,'vocabulary','image_choice','Look at the picture. What is her name?','/images/super-fun/emma.svg',NULL,'[\"Wendy\", \"Emma\", \"Mike\", \"Ken\"]','Emma','Emma 是故事裡的女孩角色，喜歡在社群媒體上通知大家消息。',1,NULL,1,'2026-07-13 15:44:19','2026-07-16 21:04:36'),(83,9,'vocabulary','image_choice','Look at the picture. What is her name?','/images/super-fun/wendy.svg',NULL,'[\"Emma\", \"Wendy\", \"Alan\", \"Ken\"]','Wendy','Wendy 喜歡在公園裡播放音樂，發現了走失的小狗 Cody。',1,NULL,1,'2026-07-13 15:44:19','2026-07-16 21:04:36'),(84,9,'vocabulary','image_choice','Look at the picture. What is his name?','/images/super-fun/ken.svg',NULL,'[\"Ken\", \"Mike\", \"Alan\", \"Emma\"]','Ken','Ken 拿出狗狗零食，把走失的狗狗 Cody 從草叢中引誘出來。',1,NULL,1,'2026-07-13 15:44:19','2026-07-16 21:04:36'),(85,9,'vocabulary','listening','Listen carefully. Which number do you hear?',NULL,'seven','[\"six\", \"seven\", \"eight\", \"nine\"]','seven','聽到的單字是 seven（七）。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(86,9,'vocabulary','listening','Listen carefully. Which number do you hear?',NULL,'nine','[\"eight\", \"nine\", \"ten\", \"six\"]','nine','聽到的單字是 nine（九）。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(87,9,'vocabulary','listening','Listen carefully. Which number do you hear?',NULL,'ten','[\"ten\", \"six\", \"seven\", \"eight\"]','ten','聽到的單字是 ten（十）。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(88,9,'vocabulary','listening','Listen carefully. Which number do you hear?',NULL,'six','[\"six\", \"eight\", \"nine\", \"ten\"]','six','聽到的單字是 six（六）。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(89,9,'sentence','ordering','Put the words in order to make a sentence.',NULL,NULL,'[]','What is your name','正確句子：What is your name?（你叫什麼名字？）',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(90,9,'sentence','ordering','Put the words in order to make a sentence.',NULL,NULL,'[]','My name is Ken','正確句子：My name is Ken.（我的名字是肯。）',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(91,9,'sentence','ordering','Put the words in order to make a sentence.',NULL,NULL,'[]','I am nine years old','正確句子：I am nine years old.（我九歲了。）',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(92,9,'sentence','fill_blank','Mike: Hi, I\'m Kim. I\'m nine years old.\nWendy: ___ are you, Alan?\nAlan: I\'m ten.',NULL,NULL,'[]','How old','完整句子是「How old are you, Alan?」，詢問年齡的句型。',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(93,9,'sentence','fill_blank','Emma: Hello, I\'m Emma. What\'s your name?\nWendy: I\'m ___.',NULL,NULL,'[]','Wendy','依照故事情境，回答自己的名字 Wendy。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(94,9,'sentence','fill_blank','Mike: Nice to meet you.\nKen: Nice to meet you, ___.',NULL,NULL,'[]','too','完整句子是「Nice to meet you, too.」，禮貌回應用語。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(95,9,'sentence','mcq','Which sentence is correct when you ask someone their age?',NULL,NULL,'[\"How old are you?\", \"How are you old?\", \"What old are you?\", \"You are how old?\"]','How old are you?','詢問年齡的正確句型是 How old are you?',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(96,9,'sentence','mcq','Someone says \"Thank you.\" What should you say?',NULL,NULL,'[\"You\'re welcome.\", \"Thank you too.\", \"I am fine.\", \"Nice to meet you.\"]','You\'re welcome.','當別人說 Thank you，禮貌的回應是 You\'re welcome.（不客氣）',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(97,9,'reading','mcq','Mike: Hi, I\'m Kim. I\'m nine years old.\nTed: I\'m Ted. My name is Ann.\n\nWho says \"I\'m nine years old\"?',NULL,NULL,'[\"Mike\", \"Ted\", \"Ann\", \"Kim\"]','Mike','從對話中可以看到，說「I\'m nine years old」的是 Mike（自稱 Kim）。',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(98,9,'reading','mcq','Wendy: Hi, I\'m Mike.\nEmma: Hello, I\'m Emma. What\'s your name?\nWendy: I\'m Wendy.\nEmma: How old are you?\nWendy: I\'m nine years old.\n\nHow old is Wendy?',NULL,NULL,'[\"nine\", \"ten\", \"eight\", \"seven\"]','nine','從對話中 Wendy 說「I\'m nine years old」，所以 Wendy 九歲。',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(99,9,'reading','mcq','Mike: How old are you, Alan?\nAlan: I\'m ten.\n\nHow old is Alan?',NULL,NULL,'[\"ten\", \"nine\", \"eight\", \"six\"]','ten','Alan 回答「I\'m ten」，所以 Alan 十歲。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(100,9,'reading','mcq','Wendy was in the park. She heard a dog barking. She found a stray dog that looked like Cody. Ken brought dog snacks to lure the dog out from the bushes. They found Cody!\n\nWhere was Wendy when she heard the dog?',NULL,NULL,'[\"in the park\", \"at school\", \"at home\", \"at the zoo\"]','in the park','故事提到 Wendy 在公園裡（in the park）聽到狗叫聲。',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(101,9,'reading','mcq','Wendy was in the park. She heard a dog barking. She found a stray dog that looked like Cody. Ken brought dog snacks to lure the dog out from the bushes. They found Cody!\n\nWho brought dog snacks?',NULL,NULL,'[\"Ken\", \"Mike\", \"Emma\", \"Alan\"]','Ken','故事提到 Ken 拿出狗狗零食（dog snacks）引誘小狗出來。',2,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(102,9,'reading','mcq','Mike, Ken, Emma, Wendy, and Alan are all new friends. They introduce themselves and ask each other questions like \"What\'s your name?\" and \"How old are you?\"\n\nWhat do new friends usually ask each other?',NULL,NULL,'[\"What\'s your name? and How old are you?\", \"Where do you live?\", \"What do you eat?\", \"What time is it?\"]','What\'s your name? and How old are you?','故事的主旨是新朋友見面時會互相詢問姓名和年齡。',1,NULL,1,'2026-07-13 15:44:19','2026-07-13 15:44:19'),(103,10,'vocabulary','image_choice','Look at the picture. How does he look?','/images/super-fun/tall.svg',NULL,'[\"tall\", \"short\", \"thin\", \"tired\"]','tall','圖片中的人物身高很高，所以是 tall（高的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-16 21:04:36'),(104,10,'vocabulary','image_choice','Look at the picture. How does she look?','/images/super-fun/short.svg',NULL,'[\"short\", \"tall\", \"strong\", \"angry\"]','short','圖片中的人物身高比較矮，所以是 short（矮的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-16 21:04:36'),(105,10,'vocabulary','image_choice','Look at the picture. How does he look?','/images/super-fun/strong.svg',NULL,'[\"strong\", \"thin\", \"sad\", \"happy\"]','strong','圖片中的人物看起來很有力氣，所以是 strong（強壯的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-16 21:04:36'),(106,10,'vocabulary','image_choice','Look at the picture. How does she look?','/images/super-fun/thin.svg',NULL,'[\"thin\", \"strong\", \"tall\", \"tired\"]','thin','圖片中的人物身材瘦瘦的，所以是 thin（瘦的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-16 21:04:36'),(107,10,'vocabulary','listening','Listen carefully. Which word do you hear?',NULL,'happy','[\"happy\", \"sad\", \"angry\", \"tired\"]','happy','聽到的單字是 happy（快樂的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(108,10,'vocabulary','listening','Listen carefully. Which word do you hear?',NULL,'sad','[\"sad\", \"happy\", \"tired\", \"angry\"]','sad','聽到的單字是 sad（傷心的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(109,10,'vocabulary','listening','Listen carefully. Which word do you hear?',NULL,'angry','[\"angry\", \"tired\", \"happy\", \"sad\"]','angry','聽到的單字是 angry（生氣的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(110,10,'vocabulary','listening','Listen carefully. Which word do you hear?',NULL,'tired','[\"tired\", \"sad\", \"angry\", \"happy\"]','tired','聽到的單字是 tired（累的）。',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(111,10,'sentence','ordering','Put the words in order to make a sentence.',NULL,NULL,'[]','I\'m short','正確句子：I\'m short.（我很矮。）',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(112,10,'sentence','ordering','Put the words in order to make a sentence.',NULL,NULL,'[]','He\'s strong','正確句子：He\'s strong.（他很強壯。）',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(113,10,'sentence','ordering','Put the words in order to make a sentence.',NULL,NULL,'[]','Are you tired','正確句子：Are you tired?（你累了嗎？）',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(114,10,'sentence','fill_blank','Mike: Are you tired?\nKen: Yes, I ___.',NULL,NULL,'[]','am','完整句子是「Yes, I am.」，肯定回答的標準句型。',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(115,10,'sentence','fill_blank','Wendy: Are you angry?\nEmma: No, I\'m not. I\'m ___.',NULL,NULL,'[]','sad','依照情境，Emma 不是生氣而是傷心（sad）。',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(116,10,'sentence','fill_blank','Alan: ___ are you?\nMike: I am fine.',NULL,NULL,'[]','How','完整句子是「How are you?」，日常問候用語。',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(117,10,'sentence','mcq','Which sentence describes someone who is very tall?',NULL,NULL,'[\"He is tall.\", \"He is short.\", \"He is thin.\", \"He is tired.\"]','He is tall.','描述身高高的正確句子是 He is tall.',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(118,10,'sentence','mcq','Your friend did a great job. What do you say?',NULL,NULL,'[\"Good job!\", \"Try again.\", \"I am sad.\", \"How old are you?\"]','Good job!','稱讚別人做得好，要說 Good job!（做得好！）',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(119,10,'reading','mcq','Mike: Hi, I\'m Mike. We can help, too.\nEmma: Hello, I\'m Emma. What\'s your name?\nWendy: I\'m Wendy.\n\nWhat does Mike say they can do?',NULL,NULL,'[\"help\", \"sing\", \"dance\", \"cook\"]','help','Mike 說「We can help, too.」，表示他們也能幫忙。',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(120,10,'reading','mcq','Mike: How old are you, Alan?\nAlan: I\'m ten.\nMike: Nice to meet you.\nAlan: Nice to meet you, too.\n\nHow old is Alan in this story?',NULL,NULL,'[\"ten\", \"nine\", \"eight\", \"seven\"]','ten','Alan 回答「I\'m ten」，所以 Alan 十歲。',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(121,10,'reading','mcq','Christmas is here. We Can Help is celebrating Christmas at the old lady\'s house. Mike even dresses like Santa Claus.\n\nWhat does Mike dress like?',NULL,NULL,'[\"Santa Claus\", \"a reindeer\", \"an elf\", \"a snowman\"]','Santa Claus','故事提到 Mike 打扮成聖誕老人（Santa Claus）。',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(122,10,'reading','mcq','Ken and Wendy are decorating the Christmas tree. Alan is preparing the meal. There are salad, an apple pie, and roast turkey.\n\nWho is preparing the meal?',NULL,NULL,'[\"Alan\", \"Ken\", \"Wendy\", \"Mike\"]','Alan','故事提到 Alan 負責準備餐點（preparing the meal）。',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(123,10,'reading','mcq','The old lady lost her dog, Cody. Wendy found a stray dog in the bushes. Ken used dog snacks to lure it out. It was Cody!\n\nWhose dog is Cody?',NULL,NULL,'[\"the old lady\'s\", \"Wendy\'s\", \"Ken\'s\", \"Mike\'s\"]','the old lady\'s','故事提到 Cody 是老奶奶（the old lady）的狗。',2,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(124,10,'reading','mcq','We Can Help is a group of friends who help others in the community. They help find lost pets and celebrate holidays with people who need company.\n\nWhat does \"We Can Help\" do?',NULL,NULL,'[\"help others in the community\", \"play video games\", \"study at school\", \"go shopping\"]','help others in the community','故事主旨是「We Can Help」是一群在社區中互助的朋友。',1,NULL,1,'2026-07-13 15:44:20','2026-07-13 15:44:20'),(125,1,'reading','mcq','Mia is at the park. She sees a rabbit and a bird. The rabbit is white. The bird is singing.\n\nWhere is Mia?',NULL,NULL,'[\"park\", \"zoo\", \"school\", \"home\"]','park','故事開頭就說 Mia is at the park（在公園）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(126,1,'reading','mcq','Mia is at the park. She sees a rabbit and a bird. The rabbit is white. The bird is singing.\n\nWhat color is the rabbit?',NULL,NULL,'[\"white\", \"black\", \"brown\", \"pink\"]','white','故事提到 The rabbit is white（兔子是白色的）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(127,1,'reading','mcq','Dad and I go to the zoo. We see a big lion and a scary tiger. My brother likes the tiger. I like the bear.\n\nWho likes the tiger?',NULL,NULL,'[\"my brother\", \"I\", \"dad\", \"the lion\"]','my brother','故事說 My brother likes the tiger（我弟弟喜歡老虎）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(128,1,'reading','mcq','Dad and I go to the zoo. We see a big lion and a scary tiger. My brother likes the tiger. I like the bear.\n\nWhat animal does \"I\" like?',NULL,NULL,'[\"bear\", \"tiger\", \"lion\", \"monkey\"]','bear','故事說 I like the bear（我喜歡熊）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(129,1,'reading','mcq','Grandma has a pig and a chicken on the farm. The pig is pink. The chicken is small.\n\nWhat color is the pig?',NULL,NULL,'[\"pink\", \"white\", \"black\", \"brown\"]','pink','故事說 The pig is pink（豬是粉紅色的）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(130,2,'reading','mcq','It is breakfast time. Ken eats bread and an egg. He drinks milk.\n\nWhat does Ken drink?',NULL,NULL,'[\"milk\", \"juice\", \"water\", \"tea\"]','milk','故事說 He drinks milk（他喝牛奶）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(131,2,'reading','mcq','It is breakfast time. Ken eats bread and an egg. He drinks milk.\n\nWhat does Ken eat for breakfast?',NULL,NULL,'[\"bread and an egg\", \"pizza and cake\", \"fish and soup\", \"hamburger and hot dog\"]','bread and an egg','故事說 Ken eats bread and an egg（肯吃麵包和蛋）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(132,2,'reading','mcq','Today is my birthday. We have pizza and cake for dinner. My friends drink juice.\n\nWhat do they eat for dinner?',NULL,NULL,'[\"pizza and cake\", \"sandwich and soup\", \"hamburger and bread\", \"fish and rice\"]','pizza and cake','故事說晚餐吃 pizza and cake（披薩和蛋糕）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(133,2,'reading','mcq','Today is my birthday. We have pizza and cake for dinner. My friends drink juice.\n\nWhat do my friends drink?',NULL,NULL,'[\"juice\", \"milk\", \"tea\", \"water\"]','juice','故事說 My friends drink juice（我朋友喝果汁）。',1,NULL,1,'2026-07-21 11:27:50','2026-07-21 11:27:50'),(134,2,'reading','mcq','Amy is thirsty. She wants water, not tea. She drinks a big glass of water.\n\nWhat does Amy want to drink?',NULL,NULL,'[\"water\", \"tea\", \"milk\", \"juice\"]','water','故事說 She wants water, not tea（她想喝水，不是茶）。',1,NU